using System;using System.IO;using System.Linq;using System.Text;using System.IO.Compression;using System.Collections.Generic;using DualSteam;
public static class CoreTests {
 static int count;static void Assert(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(IOException){rejected=true;}Assert(rejected,name);}
 public static int Main(){string temp=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Verification","Core-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{
  string digest=new string('a',64);string json="{\"tag_name\":\"v3.0.1\",\"draft\":false,\"prerelease\":false,\"assets\":[{\"name\":\"Dual-Steam-Windows.zip\",\"browser_download_url\":\"https://github.com/w-rakeeb/dual-steam/releases/download/v3.0.1/Dual-Steam-Windows.zip\",\"digest\":\"sha256:"+digest+"\",\"size\":100}]}";Assert(UpdateService.ParseRelease(json).Version==new Version(3,0,1),"stable GitHub release and checksum parsed");Reject(()=>UpdateService.ParseRelease(json.Replace("w-rakeeb/dual-steam/","someone/other/")),"foreign repository update rejected");Reject(()=>UpdateService.ParseRelease(json.Replace("sha256:"+digest,"")),"missing release checksum rejected");
  foreach(string unsafeName in new[]{"../escape.txt","Data/Native/password.dpapi","Profiles/Second/Client/config/loginusers.vdf"}){string zip=Path.Combine(temp,Guid.NewGuid()+".zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create))using(var writer=new StreamWriter(z.CreateEntry(unsafeName).Open()))writer.Write("test");Reject(()=>UpdatePackage.Validate(zip),"private or unsafe package entry rejected: "+unsafeName);}
  string stage=Path.Combine(temp,"stage"),target=Path.Combine(temp,"target");Directory.CreateDirectory(stage);Directory.CreateDirectory(target);Directory.CreateDirectory(Path.Combine(stage,"Assets"));Directory.CreateDirectory(Path.Combine(target,"Assets"));File.WriteAllText(Path.Combine(stage,"README.md"),"new");File.WriteAllText(Path.Combine(stage,@"Assets\SOURCE.md"),"new");File.WriteAllText(Path.Combine(target,"README.md"),"old");File.WriteAllText(Path.Combine(target,@"Assets\SOURCE.md"),"old");int copies=0;Reject(()=>UpdatePackage.Apply(stage,target,relative=>{if(++copies==2)throw new IOException("simulated write failure");}),"failed update rolls back");Assert(File.ReadAllText(Path.Combine(target,"README.md"))=="old"&&File.ReadAllText(Path.Combine(target,@"Assets\SOURCE.md"))=="old","all old files restored after update failure");
  string steam=Path.Combine(temp,@"Main\steam.exe");Directory.CreateDirectory(Path.GetDirectoryName(steam));File.WriteAllText(steam,"fixture");Reject(()=>SetupService.Validate(steam,Path.GetPathRoot(temp)),"drive root rejected for setup");Reject(()=>SetupService.Validate(steam,Path.GetDirectoryName(steam)),"main installation rejected as second profile");Reject(()=>SetupService.Validate(steam,Path.Combine(Path.GetDirectoryName(steam),"Second")),"nested main-installation setup rejected");SetupService.Validate(steam,Path.Combine(temp,"Separate"));Assert(true,"separate empty local setup folder accepted");
  string unicode=Path.Combine(temp,"প্রোফাইল_测试");Directory.CreateDirectory(unicode);string input=Path.Combine(unicode,"input.json"),outputFile=Path.Combine(unicode,"output.json"),script=Path.Combine(temp,"codec.ps1");string text="{\"Root\":\"প্রোফাইল_测试\"}";File.WriteAllText(input,text,new UTF8Encoding(false));File.WriteAllText(script,"param([string]$InputFile,[string]$OutputFile)\r\n$env:PSModulePath=Join-Path $PSHOME 'Modules'\r\nGet-Content -LiteralPath $InputFile -Raw -Encoding UTF8 | ConvertFrom-Json | ConvertTo-Json | Set-Content -LiteralPath $OutputFile -Encoding UTF8\r\n");Engine.Run(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File "+Engine.Quote(script)+" -InputFile "+Engine.Quote(input)+" -OutputFile "+Engine.Quote(outputFile));Assert(File.ReadAllText(outputFile).Contains("প্রোফাইল_测试"),"non-English paths survive Windows PowerShell UTF-8 handoff");
  Console.WriteLine(count+" checks passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(Directory.Exists(temp))Directory.Delete(temp,true);}}
}
